from sage.all import *
try:
 QQ(1)/QQ(0)
except ZeroDivisionError as error:
 print('expected rejection:', type(error).__name__, str(error)[:200])
else:
 raise AssertionError('division by zero was accepted')

from sage.all import ZZ
coefficients = ['1', 'not-an-integer']
try:
 [ZZ(value) for value in coefficients]
except (TypeError, ValueError) as error:
 print('rejected invalid coefficient:', type(error).__name__)
else:
 raise AssertionError('invalid coefficient was accepted')
